<?php require __DIR__.'/bootstrap.php';require __DIR__.'/layout.php';$u=require_login();$where=[];$params=[];if($u['role']!=='ADMIN'){$where[]='a.creado_por_id=?';$params[]=$u['id'];}foreach(['estado','tipo_acuerdo'] as $f){if(!empty($_GET[$f])){$where[]="a.$f=?";$params[]=$_GET[$f];}}$sql="SELECT a.*,c.nombre_completo,u.username,GROUP_CONCAT(CONCAT(d.id,':',d.tipo,':',d.estado) SEPARATOR '|') documentos FROM acuerdos a JOIN clientes c ON c.id=a.cliente_id JOIN usuarios u ON u.id=a.creado_por_id LEFT JOIN documentos d ON d.acuerdo_id=a.id".($where?' WHERE '.implode(' AND ',$where):'').' GROUP BY a.id ORDER BY a.created_at DESC LIMIT 250';$q=$db->prepare($sql);$q->execute($params);$rows=$q->fetchAll();page_start($u['role']==='ADMIN'?'Todos los acuerdos':'Mis acuerdos',$u);?><section class="panel"><form class="filters"><select name="tipo_acuerdo"><option value="">Todos los tipos</option><option>CANCELACION</option><option>CONVENIO</option></select><select name="estado"><option value="">Todos los estados</option><?php foreach(['BORRADOR','PENDIENTE_APROBACION','APROBADO','VIGENTE','CUMPLIDO','INCUMPLIDO','ANULADO'] as $s):?><option><?=e($s)?></option><?php endforeach?></select><button>Filtrar</button></form><table><thead><tr><th>Código</th><th>Cliente</th><?php if($u['role']==='ADMIN'):?><th>Agente</th><?php endif?><th>Tipo</th><th>Monto</th><th>Cuotas</th><th>Estado</th><th>Documentos</th><th>Fecha</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['codigo_acuerdo'])?></td><td><?=e($r['nombre_completo'])?></td><?php if($u['role']==='ADMIN'):?><td><?=e($r['username'])?></td><?php endif?><td><?=e($r['tipo_acuerdo'])?></td><td><?=money($r['monto_acordado'])?></td><td><?=(int)$r['numero_cuotas']?></td><td><span class="badge"><?=e($r['estado'])?></span></td><td><?php foreach(array_filter(explode('|',$r['documentos']??'')) as $item):[$docId,$docType,$docStatus]=explode(':',$item);?><div><?php if($docStatus==='DISPONIBLE'):?><a href="<?=url('descargar-documento.php?id='.(int)$docId)?>"><?=e($docType==='ACUERDO_PAGO'?'Acuerdo de pago':'Cesión de Derechos')?></a><?php else:?><small><?=e($docType)?>: <?=e($docStatus)?></small><?php endif?></div><?php endforeach?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></section><?php page_end();

